INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('18727147-0b1d-463f-a650-d85e3000493d', 'b2b2b2b2-3030-4000-8000-000000000002', 16, 'Dia 16 — Autocompaixão', 'Semana 3: Reconstruir', '{"pch": "Como um pai se compadece dos filhos\u2026 Seja gentil consigo mesmo como Deus \u00e9 com voc\u00ea.", "verse": "Sl 103,13", "lectio": "Leia Sl 103,8-14. Deus conhece nossa fragilidade.", "practice": "Hoje, trate-se como trataria seu melhor amigo.", "question": "Como voc\u00ea se trata quando falha?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;